"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["20772"],{28579(e,n,i){i.r(n),i.d(n,{metadata:()=>t,default:()=>u,frontMatter:()=>o,contentTitle:()=>h,toc:()=>d,assets:()=>l});var t=JSON.parse('{"id":"identity/dfdaily2","title":"","description":"March 21, 2009, 02:49  Oriental Morning Post","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/identity/dfdaily2.md","sourceDirName":"identity","slug":"/identity/dfdaily2","permalink":"/en/identity/dfdaily2","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"dfdaily2","title":"","hide_table_of_contents":false,"sidebar_label":"The attending physician recounts Chan\'s final days: hearing his delirious murmurs that night (Oriental Morning Post)"},"sidebar":"identitySidebar","previous":{"title":"The mystery of famous blogger Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n: suspected Yi\'an Technology trader Li Biao (Oriental Morning Post)","permalink":"/en/identity/dfdaily1"},"next":{"title":"A tearful tribute to Master Chan (collecting online fragments about Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n / Li Biao)","permalink":"/en/identity/tianyapost"}}'),a=i(74848),s=i(28453),r=i(66422);let o={id:"dfdaily2",title:"",hide_table_of_contents:!1,sidebar_label:"The attending physician recounts Chan's final days: hearing his delirious murmurs that night (Oriental Morning Post)"},h='The Attending Physician Describes Chan\'s Final Days: "That Night, I Kept Hearing His Delirious Murmuring"',l={},d=[{value:"The Attending Physician Describes Chan&#39;s Final Days: &quot;That Night, I Kept Hearing His Delirious Murmuring&quot;",id:"the-attending-physician-describes-chans-final-days-that-night-i-kept-hearing-his-delirious-murmuring-1",level:3},{value:"&quot;Living Like a Dog \u2014 Better to Break Free&quot;",id:"living-like-a-dog--better-to-break-free",level:3}];function c(e){let n={a:"a",admonition:"admonition",blockquote:"blockquote",em:"em",h1:"h1",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"the-attending-physician-describes-chans-final-days-that-night-i-kept-hearing-his-delirious-murmuring",children:'The Attending Physician Describes Chan\'s Final Days: "That Night, I Kept Hearing His Delirious Murmuring"'})}),"\n",(0,a.jsxs)(n.blockquote,{children:["\n",(0,a.jsx)(n.p,{children:"March 21, 2009, 02:49  Oriental Morning Post"}),"\n"]}),"\n",(0,a.jsxs)("div",{style:{textAlign:"center"},children:[(0,a.jsx)("img",{src:(0,r.Ay)("/img/identity/dfdaily2/cover.jpeg")}),(0,a.jsx)("br",{}),(0,a.jsxs)(n.p,{children:["This issue's cover of the ",(0,a.jsx)(n.em,{children:"Oriental Morning Post"}),(0,a.jsx)("br",{}),(0,a.jsx)("br",{})]})]}),"\n",(0,a.jsx)(n.h3,{id:"the-attending-physician-describes-chans-final-days-that-night-i-kept-hearing-his-delirious-murmuring-1",children:'The Attending Physician Describes Chan\'s Final Days: "That Night, I Kept Hearing His Delirious Murmuring"'}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.em,{children:"Fund Analysis"})," magazine confirms Muzi was indeed Chan Zhong Shuo Chan and has passed away"]}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.em,{children:'"Linjiangxian" (To the Tune of Immortal by the River)'})}),"\n",(0,a.jsx)(n.p,{children:"February 1, 2006"}),"\n",(0,a.jsx)(n.p,{children:"Turbid waves three thousand leagues of roiling muddy water,"}),"\n",(0,a.jsx)(n.p,{children:"Sitting alone in solemn solitude upon a lone peak."}),"\n",(0,a.jsx)(n.p,{children:"The dragon hides, the lion sleeps, awaiting the tempest."}),"\n",(0,a.jsx)(n.p,{children:"The heartless are all scoundrels,"}),"\n",(0,a.jsx)(n.p,{children:"Yet those with tears are heroes too."}),"\n",(0,a.jsx)(n.p,{children:"A long sword leans against heaven, starlight in splendor,"}),"\n",(0,a.jsx)(n.p,{children:"Past and present pass before the eyes and turn to void."}),"\n",(0,a.jsx)(n.p,{children:"Bowing and gazing up, one accepts whatever fate \u2014 success or failure."}),"\n",(0,a.jsx)(n.p,{children:"Half a moon above the grey-green sea,"}),"\n",(0,a.jsx)(n.p,{children:"A single reed-raft on the great river, heading east."}),"\n",(0,a.jsx)(n.p,{children:"Oriental Morning Post \u2014 Financial Weekly reporter / Lin Qi"}),"\n",(0,a.jsxs)(n.p,{children:['Upon hearing that Chan Zhong Shuo Chan (hereafter "Chan") had passed away (see last week\'s Financial Weekly A46-47 ',(0,a.jsx)(n.a,{href:"dfdaily1",children:(0,a.jsx)(n.em,{children:"\"Famous Blogger 'Chan Zhong Shuo Chan' \u2014 Post-Mortem Mystery: Is He Yi'an Technology Operator Li Biao?\""})}),"), Chan fans went nearly mad, flooding in with calls of doubt and inquiry. After calm investigation, the Financial Weekly reporter confirmed that Chan has indeed passed away."]}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:"Confirmed Deceased"})}),"\n",(0,a.jsxs)(n.p,{children:["This Tuesday, the Financial Weekly reporter finally reached a staff member at the ",(0,a.jsx)(n.em,{children:"Fund Analysis"})," editorial office. The staff member, speaking in Beijing-accented Mandarin, stated that Muzi, who wrote columns for the magazine, was Chan, and that he had already passed away at the end of October last year. His true identity could not be disclosed."]}),"\n",(0,a.jsxs)(n.p,{children:["To further confirm, the reporter contacted Dr. Liu, a physician who had traveled specifically to Guangzhou to treat Chan. Dr. Liu had written a blog post titled ",(0,a.jsx)(n.em,{children:'"Guangzhou\'s Sorrow"'}),", saying that his visit to see the patient felt less like a medical consultation and more like a spiritual baptism."]}),"\n",(0,a.jsx)(n.p,{children:'When the reporter asked whether Chan was Li Biao, Dr. Liu responded: "Why torment yourself over this? What Chan left behind for everyone is already abundant and precious. Seizing the present and grasping the future is what everyone needs to do."'}),"\n",(0,a.jsx)(n.p,{children:'Hearing this, the reporter pressed further \u2014 so does this mean Chan has truly passed away? This was the question Chan fans cared about most. Dr. Liu replied: "Draw your own conclusions."'}),"\n",(0,a.jsx)(n.p,{children:"Dr. Liu recalled in his blog the scene of treating Chan in October 2008: \"On the afternoon of October 13, I took the 3:10 PM flight to Guangzhou. It was pouring rain when we landed. At 8 PM, I finally reached the patient's residence. Walking into that 'L-shaped' bedroom, I saw Chan for the first time. A very small person, body exposed, lying on the bed, so thin it was heartbreaking. His head was large, and there were terrifying tumors on his neck.\""}),"\n",(0,a.jsx)(n.p,{children:"From the photograph of Li Biao at the November 2007 Pingxiang Innovation Capital Management inauguration ceremony, a visible lump can already be seen on the left side of his neck near the nape."}),"\n",(0,a.jsx)(n.p,{children:"Dr. Liu continued: \"That day [October 24, 2008], everyone left the hospital room before 7 PM, leaving only me to accompany Chan. Chan was running a high fever again, reaching 39.5\xb0C... So I called Chan's uncle-in-law: 'Uncle, it seems like you brought me here to be a full-time caretaker. Chan's temperature has been holding at 39.5\xb0C. If something terrible happens in the hospital, how do I explain it?' He told me he would immediately call the caretaker Old Chen to come back, but Old Chen didn't return all night either \u2014 he only came back to the hospital room at 7:40 AM the next morning. Chan's fever persisted. He wouldn't take medicine. The doctors used sedative antipyretics, but nothing could bring the fever down. Chan's consciousness was already unclear \u2014 one moment he'd say he saw someone arriving and ask me to open the door; the next he'd talk about how stocks were doing this or that, about the Taiwan dollar and so on... I spent the entire night listening to Chan's delirious murmuring.\""}),"\n",(0,a.jsx)(n.p,{children:"Later, while Dr. Liu was treating Chan, police came specifically to investigate him. Someone had filed a report from Shenzhen, claiming a quack doctor was there swindling money. Dr. Liu sensed the situation was extremely complicated."}),"\n",(0,a.jsx)(n.p,{children:'Chan wrote in his June 8, 2008 blog post: "Judging the market is not easy, but recognizing people is truly the hardest thing. A grave illness has taught me a great deal \u2014 among other things, even more about reading people. At the brink of life and death, all pretense and false affection shed their disguises, and every scheming heart is laid bare. This time, quite a few people showed their true colors upon hearing the announcement that this ID had only three months to live. The people I\'m talking about are real people in the physical world \u2014 a fine show indeed, stripping away every mask of human duplicity. Once the masks are gone, true-hearted friends and brothers-in-death naturally reveal themselves \u2014 unknown, then known."'}),"\n",(0,a.jsx)(n.p,{children:"On July 14, 2008, Chan wrote in a blog post: \"Even in illness there are true old-fashioned friendships. This ID normally hates to trouble people, but there's one friend, now one of the most powerful figures in business \u2014 the chairman of one of China's largest companies in one of the hottest industries. Compared to this ID lying sick, he's riding high. But this time, his true character really showed.\""}),"\n",(0,a.jsx)(n.p,{children:"The \"hottest industry\" very likely referred to venture capital, and the largest company in China's VC industry is Shenzhen Innovation Investment Group (Shenchuangtou), whose chairman Jin Haitao was the former CEO of Yi'an Group \u2014 and also Li Biao's close friend."}),"\n",(0,a.jsx)(n.p,{children:"Ultimately, perhaps it was fate: since Dr. Liu could do nothing more in Guangzhou, he returned to Beijing with regret and sorrow."}),"\n",(0,a.jsx)(n.p,{children:"Dr. Liu recalled: \"The greatest gain from this trip was receiving a spiritual baptism... I have always believed that as long as the patient doesn't give up, I won't give up. But at that moment, I had to say sorry to Chan \u2014 too many obstacles. Perhaps it was heaven's will. I could not continue.\""}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:'"Biao, Go Well"'})}),"\n",(0,a.jsxs)(n.p,{children:["Although ",(0,a.jsx)(n.em,{children:"Fund Analysis"})," had publicly acknowledged that Muzi was Chan, many Chan fans still refused to believe the facts."]}),"\n",(0,a.jsxs)(n.p,{children:["The Financial Weekly reporter's investigation also found that Chan had multiple articles published first in ",(0,a.jsx)(n.em,{children:"Fund Analysis"})," before appearing on his blog \u2014 strong evidence that Muzi and Chan were the same person. Moreover, Chan clearly valued the magazine deeply. Given Chan's abilities and personality, he would never write for an obscure publication. Yet he willingly let his articles appear in ",(0,a.jsx)(n.em,{children:"Fund Analysis"})," before his own blog. Since ",(0,a.jsx)(n.em,{children:"Fund Analysis"})," was co-founded by Li Biao, doesn't this provide further evidence that Chan was Li Biao?"]}),"\n",(0,a.jsxs)(n.p,{children:['A self-proclaimed "internet expert" among the netizens stated there was definitive evidence that Chan\'s blog articles were posted later than the ',(0,a.jsx)(n.em,{children:"Fund Analysis"})," website \u2014 through the Internet Archive's cached snapshots of the ",(0,a.jsx)(n.em,{children:"Fund Analysis"})," homepage from 2007, it could be seen that the magazine's articles consistently preceded Chan's blog. For instance, an article about the Hong Kong Stock Connect appeared on the ",(0,a.jsx)(n.em,{children:"Fund Analysis"})," website on August 31, 2007, but didn't appear on the blog until September 24."]}),"\n",(0,a.jsx)(n.p,{children:'One netizen, vinager, left a comment on Chan Zhong Shuo Chan\'s blog: "Because I was too close, I could never face it. Seeing so many people care about him is deeply moving. He also hoped everyone would believe he had gone wandering and would soon return... Many things must wait many years before they can be told. Real life is far more cruel than this virtual life. I want to thank his good friend Old Chen for accompanying him to the very end... Biao, go well."'}),"\n",(0,a.jsx)(n.p,{children:"Biao \u2014 who else could that be but Li Biao?"}),"\n",(0,a.jsx)(n.h3,{id:"living-like-a-dog--better-to-break-free",children:'"Living Like a Dog \u2014 Better to Break Free"'}),"\n",(0,a.jsx)(n.p,{children:"Oriental Morning Post \u2014 Financial Weekly reporter / Lin Qi"}),"\n",(0,a.jsx)(n.p,{children:"If Chan was an angel, no one would disagree."}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:"A Born Polymath"})}),"\n",(0,a.jsx)(n.p,{children:"Even when gravely ill and barely mobile, Chan managed to write nearly one article per day, reporting on his condition while analyzing the stock market and economy. Even when bedridden, he persisted in writing articles telling everyone where the market and economy were headed. His last article was published on October 10, 2008, and he passed away on October 31. In his final days, he was still thinking about his followers."}),"\n",(0,a.jsxs)(n.p,{children:["On October 5, 2008, he wrote a very high-quality article, ",(0,a.jsx)(n.em,{children:'"America\'s Bailout \u2014 A Farce"'}),", lengthy and thorough, exposing how the root of the global economic crisis was the US dollar system."]}),"\n",(0,a.jsx)(n.p,{children:"Just three days earlier, Chan had posted a safety report, mentioning that he'd discovered a pristine, extraordinary place on the frontier and planned to visit in early 2009. He playfully wrote: \"I won't reveal the location yet \u2014 being selfish for once, to keep the claws of development at bay a little longer.\""}),"\n",(0,a.jsx)(n.p,{children:"On September 25, 2008, Chan spent several hours crawling on the floor. \"This is what 'recuperation' looks like. Pathetic. Everything is stripped away. Living like a dog \u2014 better to just break free.\""}),"\n",(0,a.jsx)(n.p,{children:'Dr. Liu had mentioned that Chan had sleep disorders. On September 22, 2008, to get some sleep, Chan took a sedative pill. He was drowsy until the next day, and was furious. "Ten years ago, I could down an entire bottle and still go out drinking. How things have changed."'}),"\n",(0,a.jsxs)(n.p,{children:["Besides stock trading, Chan loved writing poetry, composing verse for every holiday and occasion. On September 13, 2008, thinking it was the Mid-Autumn Festival (it was actually a day early), he wrote a Mid-Autumn poem titled ",(0,a.jsx)(n.em,{children:'"Homesickness"'})," \u2014 his last poem on the blog."]}),"\n",(0,a.jsx)(n.p,{children:'His poems sometimes contained stock references, sometimes concealed his personal experiences, but often stopped short of full disclosure. The Mid-Autumn verse \u2014 "Too many targets, hard to expose / I raise my head beyond the stars / Looking back, torn both ways" \u2014 hinted at much, veiled in sighs.'}),"\n",(0,a.jsx)(n.p,{children:'Besides writing poetry, Chan was also a die-hard football fan. On September 11, 2008, upon arriving back in Guangzhou: "The moment I got to the serviced apartment, I heard England\'s good news. My mood was wonderful all day."'}),"\n",(0,a.jsx)(n.p,{children:'Deeply versed in Traditional Chinese Medicine and having developed his own system, Chan was also constantly searching for TCM masters to cure his illness. On August 17, 2008, he found a "miraculous healer" from Wuhan who performed just five minutes of therapy \u2014 the technique was unprecedented, the results immediate. This astonished Chan, who passionately wanted to become the healer\'s disciple. But the healer demurred, citing the secret family tradition.'}),"\n",(0,a.jsx)(n.p,{children:'Chan also had a great passion for composing music and singing. On July 7, 2008, he wrote a detailed article explaining singing techniques. Chan believed: "A person who cannot sing beautiful songs is truly pitiable. Life is short. If the human voice \u2014 this most exquisite of instruments \u2014 can accompany you through life\'s darkness and light, how beautiful that would be."'}),"\n",(0,a.jsx)(n.p,{children:"On July 1, 2008, already hospitalized, he actually wanted to go play billiards. He restrained himself in the end, hurrying back to the hospital to analyze the stock market for his followers."}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:"Cold-Blooded Trading"})}),"\n",(0,a.jsx)(n.p,{children:"Though Chan had extraordinarily diverse interests, none could overshadow his ruthless side in the capital markets."}),"\n",(0,a.jsx)(n.p,{children:"\"The market never believes in tears or nagging. You can do whatever you want, but as this ID has said, even this ID, when killing in the market, doesn't distinguish between friend and foe \u2014 because you can't tell them apart, and there's no time to try. Effective market time is too precious. When the blade flashes, getting cut is your own fault. Complaining only exposes your intelligence deficit. To become a steel warrior, to walk freely among flashing blades \u2014 hone your skills.\""}),"\n",(0,a.jsx)(n.p,{children:"When operating stocks, he was indeed like a killer wielding a butcher's knife \u2014 but perhaps only this way could one be victorious in every battle."}),"\n",(0,a.jsx)(n.p,{children:"From October 8, 2007, Chan announced a medium-term short position. The ideal top for the Shanghai index would be just above 6,100 points. Chan did not choose to crash the market to create the top. Instead, he went short at the resonance point of capital, technicals, and policy, then let the bulls destroy each other."}),"\n",(0,a.jsx)(n.p,{children:"Ultimately, Chan achieved his target: pinning the Shanghai index top firmly at 6,124.04 points, leaving many bulls stranded at the summit."}),"\n",(0,a.jsx)(n.p,{children:"Before announcing the medium-term short, Chan said something classic: \"When it's falling, think about buying points. When it's rising, think about selling points. That's how you do stocks. Otherwise, stocks are doing you.\""}),"\n",(0,a.jsxs)(n.admonition,{type:"info",children:[(0,a.jsxs)(n.p,{children:["The remainder of this article from the ",(0,a.jsx)(n.em,{children:"Oriental Morning Post \u2014 Financial Weekly"})," covers three additional major sections:"]}),(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:'1. "Three Devout Disciples Carry Forward Chan Theory"'}),' \u2014 Profiles of three key followers ("Stone Monkey," "Market Student," and "Fish Who Loves to Smile") who worked to preserve and propagate Chan Theory after the master\'s passing, creating second classrooms, compiling complete archives of blog posts, and studying both the stock trading theory and the Analects commentary.']}),(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:'2. "19 Essential Points of Chan Theory: Three Who Attain My Dao Would Suffice"'})," \u2014 A systematic summary of Chan's core trading philosophy, including:"]}),(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Economic actors who can't make money are wastes"}),"\n",(0,a.jsx)(n.li,{children:"There are no market makers, only winners and losers"}),"\n",(0,a.jsx)(n.li,{children:"Your preferences are your death traps"}),"\n",(0,a.jsx)(n.li,{children:"The market needs only watching and doing"}),"\n",(0,a.jsx)(n.li,{children:"Entanglement is always followed by a main wave"}),"\n",(0,a.jsx)(n.li,{children:"No trend means no divergence"}),"\n",(0,a.jsx)(n.li,{children:"There are only three safe buy points"}),"\n",(0,a.jsx)(n.li,{children:"Investment ultimately competes on cultivation"}),"\n",(0,a.jsx)(n.li,{children:"MACD has 90% accuracy for divergence detection"}),"\n",(0,a.jsx)(n.li,{children:'Stock "value" is just bait'}),"\n",(0,a.jsx)(n.li,{children:"Historical bottoms are not hard to find"}),"\n",(0,a.jsx)(n.li,{children:"The divergence-reversal theorem"}),"\n",(0,a.jsx)(n.li,{children:"Better to buy into declines than to buy into rallies"}),"\n",(0,a.jsx)(n.li,{children:"Equanimity in honor and disgrace is the true way"}),"\n",(0,a.jsx)(n.li,{children:"Without rhythm, there is only death"}),"\n",(0,a.jsx)(n.li,{children:"Ten types of people to never become"}),"\n",(0,a.jsx)(n.li,{children:"Holding > buying and selling"}),"\n",(0,a.jsx)(n.li,{children:"Process determines success or failure"}),"\n",(0,a.jsx)(n.li,{children:"The cleverer you are, the faster you fail"}),"\n"]}),(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"3. Practical Case Studies"})," \u2014 Detailed technical analysis of specific stocks (Kweichow Moutai, Chihong Zinc-Germanium, ICBC, Haima Auto) illustrating how Chan applied the three buy points and divergence theory in real trading."]}),(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:'4. "Scaring the Stingy Maker into Taking Flight"'}),' \u2014 Colorful anecdotes of Chan "playing with market makers," describing his psychological warfare techniques against different maker personality types ("the cold type," "the timid type," "the newcomer type"), using mock-literary language.']}),(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:'5. "My Predictions of Bad Things Keep Coming True Like a Crow"'})," \u2014 A chronological review of Chan's major prophetic calls:"]}),(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:'2002: "America\'s adjustment is about to begin" \u2014 predicting the US economic downturn years before the 2008 crisis'}),"\n",(0,a.jsx)(n.li,{children:'2005-2007: "After the 998-point bottom comes a bull market" \u2014 correctly calling the historic bottom and subsequent rally'}),"\n",(0,a.jsx)(n.li,{children:'2007 September: "6,100 points is the top, then a major correction" \u2014 nailing the exact peak at 6,124.04 points one month before it happened'}),"\n",(0,a.jsx)(n.li,{children:'Still-unverified predictions including "Japan will become a US state by 2025" and the 2019 global economic restructuring'}),"\n"]}),(0,a.jsx)(n.p,{children:'The article concludes: "Chan still has some predictions that remain unverifiable today... Can only leave it to time to test."'})]})]})}function u(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},28453(e,n,i){i.d(n,{R:()=>r,x:()=>o});var t=i(96540);let a={},s=t.createContext(a);function r(e){let n=t.useContext(s);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),t.createElement(s.Provider,{value:n},e.children)}}}]);